import subprocess,json
base=['sudo','-u','www-data','wp','--path=/var/www/ocafezinho']
commands={}
for pid in (269237,269308): commands['post_'+str(pid)]=base+['post','get',str(pid),'--fields=ID,post_status,post_author,post_date,post_modified','--format=json']
commands['future_events']=base+['cron','event','list','--hook=publish_future_post','--fields=hook,next_run_gmt,args','--format=json']
for name,cmd in commands.items():
 r=subprocess.run(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=20)
 try: data=json.loads(r.stdout)
 except Exception: data=None
 print(json.dumps({'name':name,'command':cmd,'exit_code':r.returncode,'result':data,'stderr':r.stderr.decode()},ensure_ascii=False))
